tool_input.command:
mkdir -p $TMPDIR/checkcal && cat > $TMPDIR/checkcal/Check.java << 'EOF'
import java.util.*;
public class Check {
    public static void main(String[] a) {
        TimeZone caller = TimeZone.getTimeZone("GMT-01:00");
        TimeZone forced = TimeZone.getTimeZone("GMT+04:00");
        Calendar cal = new GregorianCalendar(caller);
        cal.clear();
        cal.set(2023, Calendar.JANUARY, 1, 10, 30, 0);
        System.out.println("before: " + cal.get(Calendar.HOUR_OF_DAY) + ":" + cal.get(Calendar.MINUTE) + " millis=" + cal.getTimeInMillis());
        Calendar clone = (Calendar) cal.clone();
        clone.setTimeZone(forced);
        System.out.println("after: " + clone.get(Calendar.HOUR_OF_DAY) + ":" + clone.get(Calendar.MINUTE) + " millis=" + clone.getTimeInMillis());
        System.out.println("original still: " + cal.get(Calendar.HOUR_OF_DAY) + ":" + cal.get(Calendar.MINUTE));
    }
}
EOF
javac -d $TMPDIR/checkcal $TMPDIR/checkcal/Check.java && java -cp $TMPDIR/checkcal Check
